CREATE TYPE "planet_type" AS ENUM('terrestrial', 'gas giant', 'ice giant');--> statement-breakpoint
CREATE TABLE "planets" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "planets_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"public_id" text NOT NULL CONSTRAINT "planets_public_id_unique" UNIQUE,
	"name" text NOT NULL CONSTRAINT "planets_name_unique" UNIQUE,
	"description" text,
	"type" "planet_type" NOT NULL,
	"moons" integer DEFAULT 0 NOT NULL,
	"diameter_km" integer NOT NULL,
	"distance_from_sun_au" real NOT NULL,
	"orbital_period_days" real NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
